#define LL long long
#define ULL unsigned long long
#define rep(i, j, k) for (int i = (j); i <= (k); i++)
#define dep(i, j, k) for (int i = (k); i >= (j); i--)
#define INF 0x3f3f3f3f
#define mem(i, j) memset(i, j, sizeof(i))
#define make(i, j) make_pair(i, j)
#define pb push_back

using namespace std;

const int N = 1e5 + 10;
const int mod = 998244353;
const int M = 3e3 + 10;

int read()
{
    int sl = 0, fh = 1;
    char ch = getchar();
    while (ch < '0' || ch > '9') {
        if (ch == '-') fh = -1;
        ch = getchar();
    }
    while (ch >= '0' && ch <= '9') {
        sl = sl * 10 + ch - '0';
        ch = getchar();
    }
    return sl * fh;
}

int ksm(int x, int y)
{
    int ans = 1;
    while (y) {
        if (y & 1) ans = static_cast<LL>(ans) * x % mod;
        x = static_cast<LL>(x) * x % mod;
        y >>= 1;
    }
    return ans;
}

int n, m, a[N], w[N], f[M][M], g[M][M], inv[M << 1], sum[3];

int main()
{
    n = read();
    m = read();

    rep(i, 1, n) a[i] = read();

    rep(i, 1, n) {
        w[i] = read();
        sum[a[i]] += w[i];
        sum[2] += w[i];
    }

    rep(i, 0, 2 * m) {
        inv[i] = ksm(sum[2] + i - m, mod - 2);
    }

    dep(i, 0, m) {
        f[i][m - i] = g[i][m - i] = 1;
        dep(j, 0, m - i - 1) {
            f[i][j] = (
                static_cast<LL>(sum[1] + i + 1) * f[i + 1][j] +
                static_cast<LL>(sum[0] - j) * f[i][j + 1]
            ) % mod * inv[i - j + m] % mod;

            g[i][j] = (
                static_cast<LL>(sum[1] + i) * g[i + 1][j] +
                static_cast<LL>(sum[0] - j - 1) * g[i][j + 1]
            ) % mod * inv[i - j + m] % mod;
        }
    }

    rep(i, 1, n) {
        printf("%lld\n", static_cast<LL>(w[i]) * (a[i] ? f[0][0] : g[0][0]) % mod);
    }

    return 0;
}

